      "en": {
        "title": "Stoofvlees / Carbonnade Flamande",
        "subtitle": "The stew that tastes of a Sunday",
        "description": "Beef left to go soft in dark abbey beer, with mustardy bread melting into the sauce and a spoon of Liège syrup to round off the bitterness. It asks for an afternoon and gives you back a whole meal.",
        "instructions": [
          "Cut the beef into good big chunks — bigger than you think, they shrink. Salt and pepper them all over.",
          "Melt butter in your heaviest pot and brown the meat a few pieces at a time. Crowd the pan and it steams instead of colouring, and that colour is the whole flavour. Lift each batch out as it's done.",
          "Now the onions, chopped, into the same butter over medium heat. Let them go soft and see-through, scraping up the brown bits the meat left behind.",
          "Back in goes the beef, then the beer poured over, then the stock cube crumbled in.",
          "Spread the mustard thickly on the bread and lay the slices mustard-side down on top of the meat. Yes, really — that is what thickens it.",
          "Bay leaves, thyme, and the Liège syrup. Lid on, heat right down, and leave it for 2 to 2.5 hours. Don't stir it about; just let it be.",
          "Fish out the herbs. The bread will have fallen apart by now — stir it through and watch the sauce turn glossy and thick."
        ]
      },
