    "cookTime": "30 mins",
    "difficulty": {
      "en": "Medium",
      "nl": "Gemiddeld",
      "fr": "Moyen"
    },
    "servings": 4,
    "category": [
      "main"
    ],
    "image": "images/gentse_waterzooi.jpg",
    "isGlutenFree": false,
    "isNutFree": false,
    "isDairyFree": true,
    "isEggFree": true,
    "isVegetarian": true,
    "isVegan": true,
    "isCandidaFriendly": false,
    "isKeto": false,
    "translations": {
      "en": {
        "title": "Vegan Waterzooi",
        "subtitle": "Ghent's comfort, without the chicken",
        "description": "The creamy Ghent stew done with tofu and oat cream instead. It has no business being as good as it is, and the lemon at the end is what makes it work.",
        "instructions": [
          "Cut the carrots, leeks, celery and potatoes into small sticks, all about the same size so they cook evenly.",
          "Cut the firm tofu into bite-sized cubes and pat them properly dry — wet tofu will never colour — then fry them in olive oil until golden on several sides.",
          "In a big pot, soften the vegetables in oil for 5 minutes without letting them catch.",
          "Pour in the vegetable broth and let it simmer 15-20 minutes, until the vegetables give way to a fork but still hold their shape.",
          "Now the oat cream and the fried tofu. Warm it through gently; a hard boil will split the cream.",
          "Off the heat, the lemon juice and the chopped parsley, then nutmeg, salt and pepper. Taste it — this one usually wants more lemon than you'd think."
        ]
      },
      "nl": {
        "title": "Vegan Waterzooi",
        "subtitle": "De troost van Gent, zonder de kip",
        "description": "De romige Gentse zooi met tofu en haverroom in plaats van kip. Het heeft geen recht om zo lekker te zijn als het is, en het citroentje op het eind is wat het doet kloppen.",
        "instructions": [
          "Snijd wortelen, prei, selderij en aardappelen in staafjes, allemaal ongeveer even groot zodat ze gelijk gaar worden.",
          "Snijd de tofu in blokjes en dep ze echt droog — natte tofu kleurt nooit — en bak ze dan goudbruin in olijfolie, op meerdere kanten.",
          "Stoof de groenten in een grote pot 5 minuten aan in olie, zonder ze te laten aanbakken.",
          "Giet de groentebouillon erbij en laat 15-20 minuten sudderen, tot de groenten voor een vork wijken maar nog vorm houden.",
          "Nu de haverroom en de gebakken tofu. Warm het rustig door; hard koken doet de room schiften.",
          "Van het vuur af het citroensap en de peterselie, dan nootmuskaat, peper en zout. Proef even — deze wil meestal meer citroen dan je zou denken."
        ]
      },
      "fr": {
        "title": "Vegan Waterzooi",
        "subtitle": "Le réconfort gantois, sans le poulet",
        "description": "Le waterzooi crémeux de Gand fait au tofu et à la crème d'avoine. Il n'a aucune raison d'être aussi bon qu'il l'est, et c'est le citron de la fin qui fait tout tenir.",
        "instructions": [
          "Coupe les carottes, poireaux, céleri et pommes de terre en petits bâtonnets, tous de même taille pour qu'ils cuisent ensemble.",
          "Coupe le tofu ferme en cubes et éponge-les vraiment bien — un tofu mouillé ne dorera jamais — puis fais-les dorer à l'huile d'olive sur plusieurs faces.",
          "Dans une grande cocotte, fais fondre les légumes dans l'huile pendant 5 minutes sans les laisser accrocher.",
          "Verse le bouillon de légumes et laisse frémir 15-20 minutes, jusqu'à ce que les légumes cèdent à la fourchette tout en gardant leur forme.",
          "La crème d'avoine et le tofu doré maintenant. Réchauffe doucement; une grosse ébullition ferait trancher la crème.",
          "Hors du feu, le jus de citron et le persil, puis la muscade, le sel et le poivre. Goûte — celui-ci en réclame presque toujours plus qu'on ne croit."
        ]
      }
    },
