    "image": "images/mealdb-53366.jpg",
    "isNutFree": true,
    "isGlutenFree": false,
    "isDairyFree": true,
    "isEggFree": true,
    "isVegetarian": false,
    "isVegan": false,
    "isCandidaFriendly": false,
    "isKeto": false,
    "translations": {
      "en": {
        "title": "Beef and Broccoli Stir-Fry",
        "subtitle": "The pan must be hot enough to make a drop of water vanish",
        "description": "Everything here is prepared before the wok goes on, because from that moment the whole dish takes about three minutes. The broccoli is blanched separately so it stays green.",
        "instructions": [
          "First, marinate the beef.",
          "Stir together the beef marinade — 1 teaspoon soy sauce, 1 teaspoon Chinese rice wine, 1/2 teaspoon cornstarch, 1/8 teaspoon black pepper — in a medium bowl.",
          "Add the beef slices and stir until coated. Let it stand 10 minutes. Now prepare the sauce.",
          "Stir together the sauce — 2 tablespoons oyster sauce, 1 teaspoon Chinese rice wine, 1 teaspoon soy sauce, 60 ml chicken broth — in a small bowl. Set it aside.",
          "Now blanch or steam the broccoli.",
          "Bring a pot of water to the boil. Add the broccoli and cook until crisp-tender, about 2 minutes. Drain it thoroughly. Now stir-fry the beef.",
          "Heat a large frying pan or wok over high heat until a bead of water sizzles and vanishes on contact. Add the cooking oil and swirl to coat.",
          "Add the beef and immediately spread it over the whole surface of the wok in a single layer, ideally not touching.",
          "Let the beef fry undisturbed for 1 minute. Flip the slices over, add the garlic, and fry another 30 seconds to 1 minute until no longer pink.",
          "Now add the sauce, cornstarch and broccoli.",
          "Pour in the sauce and the cornstarch slurry — 1 teaspoon cornstarch dissolved in 1 tablespoon of water. Stir until the sauce boils and thickens, about 30 seconds. Stir in the broccoli.",
          "Serve immediately, with steamed rice or on its own."
        ]
      },
      "nl": {
        "title": "Rundvlees met broccoli uit de wok",
        "subtitle": "De pan moet zo heet zijn dat een druppel water verdwijnt",
        "description": "Alles staat hier klaar voor de wok op het vuur gaat, want vanaf dat moment duurt het hele gerecht een minuut of drie. De broccoli wordt apart geblancheerd zodat hij groen blijft.",
        "instructions": [
          "Marineer eerst het rundvlees.",
          "Roer de marinade voor het vlees — 1 theelepel sojasaus, 1 theelepel Chinese rijstwijn, 1/2 theelepel maizena, 1/8 theelepel zwarte peper — door elkaar in een middelgrote kom.",
          "Voeg de plakjes vlees toe en roer tot ze bedekt zijn. Laat 10 minuten staan. Maak nu de saus.",
          "Roer de saus — 2 eetlepels oestersaus, 1 theelepel Chinese rijstwijn, 1 theelepel sojasaus, 60 ml kippenbouillon — door elkaar in een kommetje. Zet opzij.",
          "Blancheer of stoom nu de broccoli.",
          "Breng een pan water aan de kook. Voeg de broccoli toe en kook tot hij beetgaar is, ongeveer 2 minuten. Giet hem grondig af. Nu het vlees roerbakken.",
          "Verhit een grote koekenpan of wok op hoog vuur tot een druppel water er meteen op sist en verdwijnt. Voeg de bakolie toe en zwenk ze rond.",
          "Voeg het vlees toe en spreid het meteen over het hele oppervlak van de wok in één laag, bij voorkeur zonder dat de stukjes elkaar raken.",
          "Laat het vlees 1 minuut onaangeroerd bakken. Draai de plakjes om, voeg de knoflook toe, en bak nog 30 seconden tot 1 minuut tot het niet meer rood is.",
          "Voeg nu de saus, de maizena en de broccoli toe.",
          "Giet de saus en het maizenapapje erbij — 1 theelepel maizena opgelost in 1 eetlepel water. Roer tot de saus kookt en indikt, ongeveer 30 seconden. Roer de broccoli erdoor.",
          "Dien meteen op, met gestoomde rijst of zo."
        ]
      },
      "fr": {
        "title": "Bœuf sauté au brocoli",
        "subtitle": "La poêle doit être assez chaude pour faire disparaître une goutte d'eau",
        "description": "Tout est prêt ici avant que le wok ne chauffe, parce qu'à partir de là le plat entier prend trois minutes. Le brocoli est blanchi à part pour qu'il reste vert.",
        "instructions": [
          "D'abord, fais mariner le bœuf.",
          "Mélange la marinade du bœuf — 1 cuillère à café de sauce soja, 1 cuillère à café de vin de riz chinois, 1/2 cuillère à café de fécule, 1/8 de cuillère à café de poivre noir — dans un bol moyen.",
          "Ajoute les tranches de bœuf et remue pour les enrober. Laisse reposer 10 minutes. Prépare la sauce maintenant.",
          "Mélange la sauce — 2 cuillères à soupe de sauce d'huître, 1 cuillère à café de vin de riz chinois, 1 cuillère à café de sauce soja, 60 ml de bouillon de poulet — dans un petit bol. Réserve.",
          "Blanchis ou fais cuire le brocoli à la vapeur maintenant.",
          "Porte une casserole d'eau à ébullition. Ajoute le brocoli et cuis jusqu'à ce qu'il soit tendre-croquant, environ 2 minutes. Égoutte soigneusement. Fais sauter le bœuf maintenant.",
          "Chauffe une grande poêle ou un wok à feu vif jusqu'à ce qu'une goutte d'eau grésille et disparaisse au contact. Ajoute l'huile et fais-la tourner.",
          "Ajoute le bœuf et étale-le immédiatement sur toute la surface du wok en une seule couche, de préférence sans que les morceaux se touchent.",
          "Laisse le bœuf frire sans y toucher pendant 1 minute. Retourne les tranches, ajoute l'ail, et fais frire encore 30 secondes à 1 minute jusqu'à ce qu'il ne soit plus rosé.",
          "Ajoute maintenant la sauce, la fécule et le brocoli.",
          "Verse la sauce et la liaison à la fécule — 1 cuillère à café de fécule dissoute dans 1 cuillère à soupe d'eau. Remue jusqu'à ce que la sauce bouille et épaississe, environ 30 secondes. Incorpore le brocoli.",
          "Sers immédiatement, avec du riz vapeur ou tel quel."
        ]
      }
    },
