    "category": [
      "dessert"
    ],
    "image": "images/mealdb-53386.jpg",
    "isNutFree": true,
    "isGlutenFree": false,
    "isDairyFree": false,
    "isEggFree": false,
    "isVegetarian": true,
    "isVegan": false,
